export interface CssNamedColor {
  name: string;
  hex: string;
  rgb: { r: number; g: number; b: number };
}

export function cssNamedColorsData(): CssNamedColor[] {
  return namedColorsData().map(({ name, hex, rgb }) => ({ name, hex, rgb }));
}

