// ─── HTTP Status Codes ─────────────────────────────────────────────────────────

export interface HttpStatusCode {
  code: number;
  reason: string;
  category: "1xx" | "2xx" | "3xx" | "4xx" | "5xx";
  description: string;
  spec: string;
}

