// ─── JavaScript Types ──────────────────────────────────────────────────────────

export interface JavaScriptType {
  type: string;
  typeof: string;
  example: string;
  notes: string;
}

export function javascriptTypesData(): JavaScriptType[] {
  return [
    { type: "undefined", typeof: "undefined", example: "let x; // x is undefined", notes: "A variable that has been declared but not yet assigned a value" },
    { type: "null", typeof: "object", example: "let x = null;", notes: "Intentional absence of any object value. typeof null returns 'object' (historical bug)" },
    { type: "boolean", typeof: "boolean", example: "let x = true; // or false", notes: "Logical values: true or false" },
    { type: "number", typeof: "number", example: "let x = 42; // or 3.14, NaN, Infinity", notes: "IEEE 754 double-precision floating-point. Includes NaN and Infinity" },
    { type: "bigint", typeof: "bigint", example: "let x = 9007199254740991n;", notes: "Arbitrary-precision integers. Created with 'n' suffix or BigInt()" },
    { type: "string", typeof: "string", example: "let x = 'hello'; // or \"hello\" or `hello`", notes: "Immutable sequence of UTF-16 code units" },
    { type: "symbol", typeof: "symbol", example: "let x = Symbol('description');", notes: "Unique and immutable primitive value, often used as object property keys" },
    { type: "object", typeof: "object", example: "let x = { key: 'value' };", notes: "Collection of properties. Base type for arrays, functions, dates, etc." },
    { type: "Array", typeof: "object", example: "let x = [1, 2, 3];", notes: "Ordered list. Check with Array.isArray(). typeof returns 'object'" },
    { type: "Function", typeof: "function", example: "let x = function() {}; // or () => {}", notes: "Callable object. typeof returns 'function'" },
    { type: "Date", typeof: "object", example: "let x = new Date();", notes: "Represents a single moment in time. Check with instanceof Date" },
    { type: "RegExp", typeof: "object", example: "let x = /pattern/flags;", notes: "Regular expression object. Check with instanceof RegExp" },
    { type: "Map", typeof: "object", example: "let x = new Map();", notes: "Collection of key-value pairs where any value can be used as a key" },
    { type: "Set", typeof: "object", example: "let x = new Set();", notes: "Collection of unique values of any type" },
    { type: "WeakMap", typeof: "object", example: "let x = new WeakMap();", notes: "Keys must be objects. Keys are weakly referenced (garbage collectable)" },
    { type: "WeakSet", typeof: "object", example: "let x = new WeakSet();", notes: "Members must be objects. Weakly referenced" },
    { type: "Promise", typeof: "object", example: "let x = new Promise((resolve, reject) => {});", notes: "Represents eventual completion or failure of an asynchronous operation" },
    { type: "ArrayBuffer", typeof: "object", example: "let x = new ArrayBuffer(16);", notes: "Fixed-length raw binary data buffer" },
    { type: "Int8Array", typeof: "object", example: "let x = new Int8Array(4);", notes: "Typed array of 8-bit signed integers" },
    { type: "Uint8Array", typeof: "object", example: "let x = new Uint8Array(4);", notes: "Typed array of 8-bit unsigned integers" },
    { type: "Float32Array", typeof: "object", example: "let x = new Float32Array(4);", notes: "Typed array of 32-bit floating point numbers" },
    { type: "Float64Array", typeof: "object", example: "let x = new Float64Array(4);", notes: "Typed array of 64-bit floating point numbers" },
    { type: "Error", typeof: "object", example: "let x = new Error('message');", notes: "Base class for runtime errors. Subtypes: TypeError, RangeError, ReferenceError, etc." },
    { type: "NaN", typeof: "number", example: "let x = NaN; // Not-a-Number", notes: "Result of invalid numeric operations. typeof NaN is 'number'. NaN !== NaN" },
    { type: "Infinity", typeof: "number", example: "let x = 1/0; // Infinity", notes: "Positive or negative infinity. Also -Infinity" },
    { type: "JSON", typeof: "object", example: "JSON.parse('{}'); JSON.stringify({});", notes: "Namespace with parse and stringify methods for JSON data" },
    { type: "Math", typeof: "object", example: "Math.PI, Math.floor(), Math.random()", notes: "Namespace with mathematical constants and functions" },
    { type: "Proxy", typeof: "object", example: "let x = new Proxy(target, handler);", notes: "Enables defining custom behavior for fundamental operations" },
    { type: "Generator", typeof: "object", example: "function* gen() { yield 1; }; let g = gen();", notes: "Return values lazily. Created by generator functions (function*)" },
    { type: "AsyncGenerator", typeof: "object", example: "async function* gen() { yield 1; };", notes: "Asynchronous generator function returning values lazily" },
  ];
}

